window.TEXTP = window.TEXTP || {};
window.TEXTP["76.9"] = [[["p","Вот это всё, что пришло в книге «аль-Мустадрак». Ты видишь, что здесь не упоминается ни ′Али, ни члены семьи пророка (да благословит его Аллах и приветствует), ни их право на правление. Если это не является очевидной ложью при приведении источников хадиса, то это, как минимум, скверная подтасовка."],["p","Затем как это может быть правильным, если данная сура была ниспослана в Мекке, как это пришло в «ад-Дурр», 6/263. Тогда даже не было членов семьи пророка (да благословит его Аллах и приветствует), ибо ′Али женился на Фатыме в Медине уже после переселения, как это известно."],["p","Если тебе нужен более подробный разбор ложности этой истории, которую он отнёс к ас-Са′ляби, то вернись к ответу шейха ислама Ибн Теймии шииту Ибн уль-Мутаххиру аль-Хилли, 4/10-15. Сравни те версии хадиса, которые привёл Ибн уль-Мутаххир, и те версии, которые привёл ′Абд уль-Хусейн, и ты увидишь, что ′Абд уль-Хусейн сократил их, чтобы скрыть то, что указывает на их ложность."],["p","Аль-Хумейни также указал на этот ложный хадис и принял его, сказав на стр. 154-155: <i>«Этот аят: </i><b>\"</b>С<b>егодня Я ради вас сделал полной вашу религию\" </b><i>был ниспослан после прощального хаджа после того, как правитель верующих (′Али) был объявлен имамом. И об этом свидетельствуют как шииты, так и сунниты». </i>"],["p","Именно так шииты следуют друг за другом (от предков к поздним поколениям) в возведении лжи на посланника Аллаха (да благословит его Аллах и приветствует) и возведении навета на мусульман. Нет в них какой-либо набожности или стеснительности."],["p","Также аль-Хумейни издевается и запутывает читателей: здесь он утверждает, что этот аят был ниспослан после прощального хаджа, но на стр. 150 он говорит: <i>«Этот аят был ниспослан во время прощального хаджа». </i>"],["p","Эти (последние) его слова являются верными и соответствуют достоверным хадисам, как мы уже говорили. Но я не думаю, что аль-Хумейни высказал это слово, соглашаясь с суннитами. Он просто запутывает читателя или же скрывает свои истинные убеждения!»."],["sep",""],["p","ВОПРОС № 12: ′АБД УЛЬ-ХУСЕЙН В КНИГЕ «АЛЬ-МУРАДЖА′АТ» АРГУМЕНТИРУЕТ ВЫДУМАННЫМ ХАДИСОМ, ЧТОБЫ ОБРУГАТЬ МУ′АУИЮ (ДА БУДЕТ ДОВОЛЕН ИМ АЛЛАХ)"],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «ад-Да′ифа», 10/611, после хадиса № 4930</b><sup class=\"fn\">267</sup><b>: </b>"],["n",[[267,"В этом хадисе сказано: <b><i>«Если вы увидите Му′ауию на моём минбаре, то убейте его!». </i></b>Хадис является выдуманным (мауду′)."]]],["p","«На этот хадис опирался шиит (′Абд уль-Хусейн) в книге «аль-Мураджа′ат», см. сноску на стр. 89, где он, опираясь на него, порочит Му′ауию. При этом он закрывает глаза на то, что если человек опирается на этот хадис, ругая Му′ауию, то из этого следует ругань в адрес каждого сподвижника, который видел, как Му′ауию обращается к людям с проповедью, стоя на минбаре пророка (да благословит его Аллах и приветствует), (но не убил его). Мы просим у Всевышнего Аллаха защиты от страстей и оставления без помощи!»."],["sep",""]],[["p","ВОПРОС № 13: ′АБД УЛЬ-ХУСЕЙН, АВТОР КНИГИ «АЛЬ-МУРАДЖА′АТ» СЧИТАЕТ, ЧТО ЦЕЛЬ ОПРАВДЫВАЕТ СРЕДСТВА, ДАЖЕ ЕСЛИ РЕЧЬ ИДЁТ О НЕОБХОДИМОСТИ ВОЗВЕСТИ ЛОЖЬ НА ПОСЛАННИКА АЛЛАХА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ)"],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «ад-Да′ифа», 10/624, после хадиса № 4933</b><sup class=\"fn\">268</sup><b>: </b>"],["n",[[268,"В этом хадисе сказано: <b><i>«О Умм Саляма! Поистине, ′Али таков, что его плоть из моей плоти, а его кровь из моей крови. Он подобен положению Харуна возле Мусы, за исключением лишь того, что после меня уже не будет пророка». </i></b>Хадис является выдуманным (мауду′)."]]],["p","«<b>Примечание</b>: шиит (′Абд уль-Хусейн) привёл этот хадис в своей книге «аль-Мураджа′ат», стр. 141, где он привёл в общем три хадиса. Он аргументировал ими в теме о словах пророка (да благословит его Аллах и приветствует), с которыми он обратился к ′Али, когда оставлял его управлять Мединой во время похода на Табук: <b><i>«Ты по отношению ко мне подобен положению Харуна возле Мусы…». </i></b>Шиит аргументировал этими хадисами в пользу того, что эти слова касаются не только этой ситуации. Так вот, это — один из этих его хадисов."],["p","И всё это еще раз подтверждает в глазах каждого справедливого, что этот шиит в своей аргументации следует правилу: «Цель оправдывает средства». Именно поэтому его не заботит нахождение таких доводов, которые были бы достоверны от пророка (да благословит его Аллах и приветствует). Его главная задача — это нахождение таких хадисов, которые помогут ему осуществить его цель, даже если они являются слабыми."],["p","Также из его подтасовок то, что он берет такие хадисы, которые приводятся в книгах сунны с приведением конкретных источников их нахождения, и при этом он ограничивается отнесением хадиса к той книге, в которой он его нашёл. При этом он точно указывает том и страницу, на которой находится хадис. Это и есть самое настоящее введение в заблуждение, ведь он не упоминает конкретных авторов, которые изначально приводили этот хадис. Ведь если бы он сделал это, то оказался бы подобен тем, о которых Аллах сказал: <b>«Они разрушают свои дома собственными руками»</b><sup class=\"fn\">269</sup>."],["n",[[269,"Сура «аль-Хашр», аят 2."]]],["p","Например, возьми этот хадис. Шиит отнёс его к книгам «аль-Канз» и «Мунтахаб», и ничего к этому не добавил. А ведь в этих двух книгах сказано, что данный хадис передал аль-′Укейли. Но шиит не стал упоминать аль-′Укейли, ибо это сразу указало бы на слабость данного хадиса, так как имеется в виду, что аль-′Укейли привёл его в своей книге \"ад-Ду′афа\"<sup class=\"fn\">270</sup>»."],["n",[[270,"Данная книга посвящена слабым передатчикам хадисов, что видно из её названия."]]],["sep",""],["h2","ВОПРОС № 14: ПРИМЕРЫ ТОГО, КАК ШИИТЫ ЛГУТ, ВОЗВОДЯТ НАВЕТ И ПОРОЧАТ АБУ БАКРА АС-СЫДДИКА (ДА БУДЕТ ДОВОЛЕН ИМ АЛЛАХ)"],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «ад-Да′ифа», 10/629-630, после хадиса № 4935</b><sup class=\"fn\">271</sup><b>: </b>"],["n",[[271,"Этот длинный хадис также посвящен различным достоинствам ′Али (да будет доволен им Аллах). Хадис является слабым (да′иф)."]]]],[["p","«Этот хадис привёл шиит (′Абд уль-Хусейн) в своей книге «аль-Мураджа′ат», стр. 147-148, среди тех хадисов, которые он приводит как достоверные (как он обычно это делает), ибо они соответствуют его страстям. Однако он не обратил внимания на следующие слова (в этом слабом хадисе): <b><i>«(Я оставляю в качестве наследства) то, что оставляли пророки до меня: Книгу Господа и Сунну пророка». </i></b>Это соответствует тому, что пришло в хадисе со слов Абу Бакра (да будет доволен им Аллах): <b><i>«Мы (пророки) не оставляем наследство. Всё, что мы оставили (из имущества), (является) милостыней». </i></b>"],["p","Это — то, за что шииты порицают Абу Бакра ас-Сыддика (да будет доволен им Аллах). За это они порочат его так, как пожелали их страсти и заблуждения, ибо он не передал наследство пророка (да благословит его Аллах и приветствует) госпоже Фатыме (да будет доволен ею Аллах). Абу Бакр (да будет доволен им Аллах) поступил согласно этому хадису, который передали от него аль-Бухари и Муслим. То же самое передала целая группа благородных сподвижников (да будет доволен ими Аллах): ′Умар, ′Усман, Са′д, Тальха, аз-Зубейр, ′Абд ур-Рахман ибн ′Ауф, ′Аиша и другие. См. том 5 книги «ас-Сахиха», хадис № 2038. Всё это указывает на ложь шиитов и их невежество, а во главе их Ибн уль-Мутаххир аль-Хилли. В своей книге «Минхадж», стр. 35, он утверждает, что Абу Бакр был единственным, кто передал этот хадис."],["p","Его хорошо и подробно опроверг шейх ислама Ибн Теймия, да воздаст ему Аллах благом, в книге «Минхадж ас-Сунна», 2/157-165. Кто желает еще больше убедиться во лжи и заблуждениях шиитов, тот пусть вернется к этой книге."],["p","Также я увидел, как аль-Кулейни в своей книге «аль-Кафи» (шииты считают эту книгу такой же достоверной, как мы считаем «Сахих» аль-Бухари) передал (1/32), что Абу ′Абдуллах (Джа′фар ибн Мухаммад ас-Садик), да помилует его Аллах, сказал: <i>«Поистине, ученые — это наследники пророков, а пророки не оставляли в качестве наследства ни дирхамов, ни динаров. Они оставляли лишь свои хадисы, и тот, кто взял что-то из них, обрёл великую долю!». </i>"],["p","И это еще раз подтверждает хадис Абу Бакра ас-Сыддика (да будет доволен им Аллах)»."],["sep",""],["p","ШИИТЫ ОСПАРИВАЮТ, ЧТО ЛУЧШИМИ ЛЮДЬМИ ПОСЛЕ ПОСЛАННИКА АЛЛАХА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) БЫЛИ АБУ БАКР И ′УМАР (ДА БУДЕТ ДОВОЛЕН ИМИ АЛЛАХ)"],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «ад-Да′ифа», 10/660, после хадиса № 4951</b><sup class=\"fn\">272</sup><b>:</b>"],["n",[[272,"Ниже шейх аль-Альбани будет разбирать хадис, в котором Ибн ′Умар (да будет доволен Аллах им и его отцом) сказал: <i>«При жизни пророка (да благословит его Аллах и приветствует) мы говорили, что посланник Аллаха является лучшим из людей, а затем — Абу Бакр, а затем — ′Умар. А (′Али) ибн Аби Талибу было даровано три качества, и если бы мне было даровано хоть одно из них, это было бы любимей для меня, чем красные верблюды…». </i>"]]]],[["p","«В этих словах Ибн ′Умара есть то, во что не веруют шииты. В них говорится, что лучшими людьми после посланника Аллаха (да благословит его Аллах и приветствует) были Абу Бакр и ′Умар. Они очень сильно спорят на эту тему, приводя ложные аргументы, и на этом поприще проходят через все пустыри и труднопроходимые места, и отворачиваются от достоверных хадисов (например, эти слова Ибн ′Умара), обращаясь к слабым и выдуманным хадисам."],["p","Этот шиит (′Абд уль-Хусейн) и подобные ему берут из религиозных текстов то, что соответствует их страстям, и оставляют то, что им противоречит. Как же они похожи на тех, к кому обращается Всевышний Аллах, говоря: <b>«Неужели вы станете веровать в одну часть Писания и отвергать другую часть? Воздаянием тому, кто совершает подобное, будет позор в мирской жизни, а в День Воскресения они будут подвергнуты еще более ужасным мучениям. Аллах не находится в неведении о том, что вы совершаете»</b><sup class=\"fn\">273</sup>»."],["n",[[273,"Сура «аль-Бакара», аят 85."]]],["sep",""],["p","ВОПРОС № 15: РАЗБОР СИТУАЦИИ В «ГАДИР ХУММ» И АРГУМЕНТАЦИЯ АВТОРА КНИГИ «АЛЬ-МУРАДЖА′АТ» ТАКИМИ ХАДИСАМИ, КОТОРЫЕ НЕ ЯВЛЯЮТСЯ ДОСТОВЕРНЫМИ"],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «ад-Да′ифа», 10/680-682, после хадиса № 4961</b><sup class=\"fn\">274</sup><b>: </b>"],["n",[[274,"Речь идёт о длинном хадисе, который начинается со слов: <b><i>«О люди! Поистине, Проницательный и Ведающий (Аллах) сообщил мне, что каждый пророк проживал только половину срока, который проживал пророк, бывший до него. И, поистине, я думаю, что вот-вот уже меня позовут, и я отвечу. И, поистине, я буду спрошен и вас спросят. Что же вы ответите?!», </i></b>и так далее до конца хадиса. И среди прочего в этом хадисе сказано: <b><i>«О люди! Поистине, Аллах — мой Покровитель, а я — покровитель верующих, и я ближе к ним, чем они сами. Если я являюсь чьим-то покровителем, то его покровителем является и ′Али. О Аллах! Будь близок к тому, кто близок к нему, и враждуй с тем, кто враждует с ним!». </i></b>Хадис является слабым (да′иф)."]]],["p","«Что касается шиита (′Абд уль-Хусейна), то он сказал об этом хадисе на стр. 187: <i>«Его передал ат-Табарани и другие от Зейда ибн Аркама по такой цепочке передатчиков, которую ученые единогласно считают достоверной», </i>и затем он привёл этот хадис целиком, опустив лишь некоторые слова в начале хадиса."],["p","Я скажу: эти краткие слова шиита содержат в себе два греха (и я не говорю: две ошибки)."],["p","<b>Во-первых</b>, он сказал: <i>«…по такой цепочке передатчиков, которую ученые единогласно считают достоверной». </i>Это — очевидная ложь. Поистине, такое заявление невозможно утвердить, даже если оно изойдет от надежного ученого, который является специалистом в хадисоведении. Что же сказать о том, если такое заявляет тот, кто не имеет к этой науке никакого отношения?! Более того он — один из тех, от кого мы видим только многочисленную ложь, как мы уже многократно разъясняли."]],[["p","Я приведу тебе довод на мои слова: когда он решил утвердить это ложное заявление, он в сносках не сумел сделать ничего, кроме как добавить к этому еще одно ложное заявление и сказать: <i>«О достоверности этого хадиса сказали многие выдающиеся ученые. Достоверность этого хадиса признал даже Ибн Хаджар в \"ас-Сауа′ик\", стр. 25». </i>"],["p","Я скажу: он не сумел найти никого, кто назвал бы этот хадис достоверным, кроме этого Ибн Хаджара. Причём речь не идёт о хафизе аль-′Аскаляни. Он имеет в виду (Ибн Хаджара) аль-Хейтами, который был специалистом по фикху. И, к сожалению, аль-Хейтами в этой книге, действительно, назвал эту цепочку передатчиков достоверной."],["p","Такое заявление не принимается от таких, как он, ибо он не относился к знатокам науки хадисоведения. Среди передатчиков этого хадиса аль-Анматы, которого аль-′Аскаляни назвал слабым. Как же эта цепочка передатчиков может быть достоверной?! И как вообще можно говорить о наличии единогласного мнения о её достоверности?!"],["p","<b>Во-вторых</b>, он сказал, что этот хадис передан от Зейда ибн Аркама, хотя, на самом деле, хадис был передан от Хузейфы ибн Асида, как ты видишь. Мне кажется, что он намеренно изменил имя сподвижника, к которому относили этот хадис, чтобы ввести людей в заблуждение. Он часто поступает так. Пусть Аллах поступит с ним так, как он заслуживает!"],["p","И знай, что мы сейчас говорим конкретно об этой цепочке передатчиков и об этой версии хадиса. Пусть никто не возражает нам и не говорит, что хадис о «гадир хумм» пришёл по многочисленным путям и что он, без всяких сомнений, является достоверным. Мы скажем: да, в общем этот хадис достоверен, однако его версии сильно отличаются друг от друга. Те части хадиса, которые одинаковы в различных версиях, являются достоверными. Например, слова пророка (да благословит его Аллах и приветствует): <b><i>«Если я являюсь чьим-то покровителем, то его покровителем является и ′Али. О Аллах! Будь близок к тому, кто близок к нему, и враждуй с тем, кто враждует с ним!». </i></b>У этих слов есть достоверные пути передачи. Я собрал многие из них в книге «ас-Сахиха», 1750."],["p","Если же какие-то части в разных версиях отличаются, то необходимо возвращаться к цепочкам передатчиков. Если цепочка передатчиков достоверна, то мы принимаем текст хадиса, а если она не является достоверной, то мы не принимаем текст хадиса."],["p","Шиит же пытается усилить одни версии хадиса посредством других, но так нельзя делать. Это является очевидным, и это не скрыто от обладателей разума. Приверженцы страстей часто используют хадисы со слабой цепочкой передатчиков, если в этих хадисах пришло что-то, чего нет в достоверных хадисах, а затем они называют эти слабые хадисы достоверными, имея в виду, что основа этого хадиса является достоверной. Но проблема в том, что они аргументируют именно той версией хадиса, которая достоверной не является."],["sep",""]],[["p","<b>Затем наш шейх привёл различные версии вокруг того, что произошло в «гадир хумм», а затем сказал на стр. 684-687:</b>"],["p","«<b>Примечание</b>: отсюда ты понимаешь, что даже передатчики хадисов, не говоря уже об имамах, передававших хадис в своих книгах, разногласят в тексте этого хадиса. Некоторые приводят его в длинном виде, а некоторые — кратко."],["p","Ты можешь видеть несправедливость этого шиита, переход им границ и ненависть с его стороны к имамам сунны, когда он привёл некоторые версии этого хадиса, и среди них версию, которую передал ан-Насаи со слов Зейда, а затем сказал на стр. 190:"],["p","<i>«Этот хадис передал Муслим по разным путям передачи</i><sup class=\"fn\">275</sup><i> от Зейда ибн Аркама. Однако Муслим сократил его и разобрал на куски. Именно так они поступают!». </i>"],["n",[[275,"В сносках шейх аль-Альбани сказал: <i>«Его слова \"по разным путям передачи\" являются очередным примером его многочисленной лжи. Как мы уже говорили, Муслим передал его только через цепочку Ибн Хиббана. Точно также и Ахмад. Эта и еще другая его ложь будут разъяснены далее». </i>"]]],["p","Именно так он сказал! Пусть Аллах запечатает его уста! Как же мала его стеснительность! Что заставило его обвинить имама Муслима в том, что именно он сократил этот хадис (если это сокращение и имело место), а не те передатчики, которые выше него?! Как можно обвинять в этом Муслима, если точно также и имам Ахмад привёл этот хадис в таком же сокращенном виде?!"],["p","Затем что он скажет о ан-Насаи и других (имамах), которые передали этот хадис через другие пути передачи, и в некоторых их версиях хадис немного длиннее, а в некоторых — короче?! Особенно обрати внимание на ту версию, которую передал ат-Тирмизи. Неужели все они сократили и обрезали этот хадис?!"],["p","Более того, что скажет этот несправедливый шиит о том, как поступил аль-Хаким, которого обвиняли в шиизме?! Почему он не обвиняет аль-Хакима в том, что он «сократил» хадис, если аль-Хаким привёл только часть этого хадиса и сказал: <i>«И этот хадис имеет более длинный вид»</i>?! Разве аль-Хаким не больше Муслима заслуживает того, чтобы быть обвиненным в «сокращении» хадиса, если бы это «сокращение» было преступлением?! Однако правду сказал посланник Аллаха (да благословит его Аллах и приветствует): <b><i>«Если ты не стесняешься, то делай, что хочешь!». </i></b>"],["p","И по удивительному предопределению Аллаха получилось так, что Аллах посрамил этого шиита, который обвинял имама Муслима, сделав, так, что этот шиит впал в то же, в чём он обвинял Муслима. Именно этот шиит стал сокращать версии хадисов и обрезать их, следуя за своими страстями. Он сначала попытался обругать имама Муслима, но его попытка потерпела крах, а затем он сказал:"]],[["p","<i>«Также передается, что Са′д сказал: \"Когда мы были с посланником Аллаха (да благословит его Аллах и приветствует) и достигли гадир хумм, люди остановились…\"».</i>"],["p","И далее он упомянул хадис. Текст этого хадиса является достоверным, но его цепочка передатчиков является слабой, ибо среди его передатчиков есть неизвестный человек. И в самом тексте этого хадиса есть то, что указывает на слабость его передатчика. В начале этого хадиса сказано: <i>«Мы находились вместе с посланником Аллаха (да благословит его Аллах и приветствует) на пути в Мекку, куда он направлялся, и когда мы достигли…», </i>и до конца хадиса."],["p","Именно так этот хадис приведён у ан-Насаи, к которому шиит его отнёс. Но этот шиит убрал из этого хадиса следующие слова: <i>«…на пути в Мекку, куда он направлялся…», </i>не оставив даже никаких примечаний. Он боялся, что к его читателям проникнут сомнения относительно достоверности самой этой истории<sup class=\"fn\">276</sup>. Он не разбирается в этой науке и не может устранить эти сомнения, например, сказав: «Основа этого хадиса является достоверной»."],["n",[[276,"Так как пророк (да благословит его Аллах и приветствует) остановился в «гадир хумм», когда возвращался из Мекки в Медину, а не тогда, когда направлялся в Мекку из Медины."]]],["p","Что касается слов <i>«…на пути в Мекку, куда он направлялся…», </i>то это — ошибка со стороны некоторых передатчиков хадиса. Ведь в других цепочках передачи от Зейда и других сподвижников одинаково говорится о том, что это случилось, когда пророк (да благословит его Аллах и приветствует) возвращался с прощального хаджа. Сам шиит упомянул некоторые версии, в которых об этом говорится. См. стр. 188-189."],["p","Из этого ты понимаешь, что в отношении этого шиита можно использовать следующую пословицу: «Она обвиняет других в том недуге, который в ней самой!»."],["sep",""],["p","ВОПРОС № 16: НЕНАВИСТЬ ШИИТОВ К АНАСУ ИБН МАЛИКУ (ДА БУДЕТ ДОВОЛЕН ИМ АЛЛАХ). ВЗГЛЯНИ НА СЛОВА АВТОРА КНИГИ «АЛЬ-МУРАДЖА′АТ»"],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «ад-Да′ифа», 10/688-689, после хадиса № 4961: </b>"],["p","«Также посмотри, как шиит на стр. 195 говорит: <i>«Вероятно, их (то есть некоторых сподвижников) заставила сидеть та ненависть, которая была у них к выполнению обязанностей свидетельства. Например, Анас ибн Малик». </i>"],["p","Я скажу: он имеет в виду то, что ′Али (да будет доволен им Аллах) призвал в свидетели тех сподвижников, которые слышали слова посланника Аллаха (да благословит его Аллах и приветствует), сказанные им в день «гадир хумм». ′Али (да будет доволен им Аллах) призвал их засвидетельствовать, что пророк (да благословит его Аллах и приветствует), действительно, произнёс эти слова. Тогда группа людей встала и засвидетельствовала. Так вот шиит (да поступит с ним Аллах так, как Он заслуживает) утверждает, что Анас (да будет доволен им Аллах) не встал из-за своей ненависти к этому свидетельству."]],[["p","Враг Аллаха лжёт! Анас прислуживал посланнику Аллаха (да благословит его Аллах и приветствует) в течение десяти лет, и посланник Аллаха (да благословит его Аллах и приветствует) обращался за него с мольбой, прося для него блага у Аллаха. Анас не таков, чтобы скрывать свидетельство!"],["p","Шиит произнёс эти лживые слова, а затем попытался подкрепить их двумя хадисами:"],["p","В первом его хадисе утверждается, что ′Али (да будет доволен им Аллах) сказал Анасу: <i>«Почему ты не встаёшь вместе со сподвижниками посланника Аллаха (да благословит его Аллах и приветствует) и почему ты не свидетельствуешь о том, что слышал в тот день от пророка?!». </i>Анас ответил: <i>«О правитель верующих! Я уже стар и забыл!». </i>′Али сказал: <i>«Если ты лжёшь, то пусть Аллах нашлёт на тебя болезнь, которую не скроет твоя чалма!». </i>И не успел он встать, как его лицо покрылось проказой, и он после этого говорил: <i>«Меня настигла мольба праведного раба!». </i>"],["p","Я скажу: это — шиитский хадис, наполненный измышлениями и грехом. Это — один из многочисленных их хадисов, не имеющих никакой основы. Сам этот шиит не указал ни один источник из сборников сунны, где можно было бы найти эту историю."],["p","Что касается суннитских книг, то ни в одной из них нет такой истории. Что же касается шиитских книг, то, кажется, он сам понимает, что если бы он указал в качестве источника такой истории одну из шиитских книг, то это наоборот опозорило бы эту историю. В любом случае, в этой истории нет никаких доказательств, (так как она выдумана)»."],["sep",""],["p","ВОПРОС № 17: АРГУМЕНТАЦИЯ СЛАБЫМ ХАДИСОМ В ПОЛЬЗУ ТОГО, ЧТО ′АИША (ДА БУДЕТ ДОВОЛЕН ЕЮ АЛЛАХ) НЕ БЫЛА ЛУЧШЕ САФИЙИ (ДА БУДЕТ ДОВОЛЕН ЕЮ АЛЛАХ)"],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «ад-Да′ифа», 10/700, после хадиса № 4963</b><sup class=\"fn\">277</sup><b>:</b>"],["n",[[277,"В этом хадисе говорится, что Сафийя бинт Хуайй (да будет доволен ею Аллах) рассказывала: <i>«Однажды до меня дошло, что Хафса и ′Аиша что-то говорят обо мне, и когда ко мне пришёл посланник Аллаха (да благословит его Аллах и приветствует), я сказала ему об этом, на что он сказал: </i><b><i>«Почему ты не сказала им: \"Как вы можете быть лучше меня, если мой муж — Мухаммад, мой отец — Харун, а мой дядя — Муса?!\"?». </i></b>Хадис является слабым (да′иф)."]]],["p","«Шиит (′Абд уль-Хусейн) в своей книге «аль-Мураджа′ат», стр. 239, сделал вид, что не знает о слабости этого хадиса. Он аргументировал им в пользу того, что ′Аиша (да будет доволен ею Аллах) не была лучше Сафии и остальных жён пророка (да благословит его Аллах и приветствует, и да будет Он доволен его женами)."],["p","На его удивительное невежество (или же он просто сделал вид, что не знает) указывает то, что он отнёс этот хадис к ат-Тирмизи, но не упомянул, что ат-Тирмизи считал этот хадис слабым и сказал: <i>«Хадис редкий (гариб)…»</i><sup class=\"fn\">278</sup><i>. </i>Также он не знал (или сделал вид, что не знает) о том, что Ибн ′Абд уль-Барр также указал на слабость этого хадиса. Однако это не является удивительным от него, ведь он возводит явную ложь на ученых, что мы уже многократно разъясняли»."],["n",[[278,"Ат-Тирмизи после этого сказал: <i>«Эта его цепочка передатчиков не является крепкой». </i>"]]],["sep",""]],[["p","ВОПРОС № 18: АВТОР КНИГИ «АЛЬ-МУРАДЖА′АТ» БРАНИТ ′АИШУ, СУПРУГУ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ, И ДА БУДЕТ ДОВОЛЕН ЕЮ АЛЛАХ)"],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «ад-Да′ифа», 10/702-703, после хадиса № 4946</b><sup class=\"fn\">279</sup><b>: </b>"],["n",[[279,"Этот хадис является очень слабым. В нём говорится о том, что ′Аиша (да будет доволен ею Аллах) солгала пророку (да благословит его Аллах и приветствует) из-за того, что ревновала его к другим женам, и из-за этой лжи пострадали другие люди. Среди передатчиков этого хадиса Абу Му′аз Сулейман ибн уль-Аркам аль-Ансари — слабый. Также среди его передатчиков Яхья ибн Са′ид аль-Умави, который был правдивым, но иногда передавал странные хадисы."]]],["p","«А еще более отвергаемо то, что он упомянул от ′Аиши, будто бы она сказала: <i>«Я не считаю, что он похож!»</i><sup class=\"fn\">280</sup><i>. </i>Шиит ′Абд уль-Хусейн воспользовался этими словами в своей книге «аль-Мураджа′ат» самым худшим образом. Он стал опираться на эти слова и обвинил госпожу ′Аишу в её нравах и в её религии. Он сказал на стр. 247-248:"],["n",[[280,"Имеется в виду, что она намеренно солгала. См. предыдущую сноску."]]],["p","<i>«И достаточно тебе в качестве примера того, что она, подчинившись своим эмоциям, поддержала ту клевету, которую возводили клеветники, которые сказали, возводя клевету и проявляя вражду, о госпоже Марии и её сыне Ибрахиме то, что сказали. Затем Аллах объявил о том, что она (Мария) непричастна к этим несправедливым обвинениям, причём Аллах объявил об этом через правителя верующих (′Али). </i><b>\"Аллах вернул неверующих в ярости, и они не обрели добра\"</b><sup class=\"fn\">281</sup><i>».</i>"],["n",[[281,"Сура «аль-Ахзаб», аят 25."]]],["p","А затем он оставил следующее примечание:"],["p","<i>«Если кто-либо хочет подробнее ознакомиться с этой скверной историей, то пусть вернется к книге \"аль-Мустадрак\" аль-Хакима, том 4, стр. 39, или же пусть вернется к \"Тальхису\" аз-Захаби». </i>"],["p","Он имеет в виду этот отвергаемый хадис, (который мы упомянули)."],["p","Посмотри на его хитрость и скверну: он не только опирается на этот очень слабый хадис, он еще и не приводит его текст так, как он пришёл, подтасовывая и вводя людей в заблуждение. Ведь если бы он привёл текст этого хадиса, то каждый обладатель разума и религии понял бы, что ′Аиша непричастна к тому, что ей было приписано в этом отвергаемом хадисе. Она так же непричастна к этому, как и была непричастна к тому, в чём её обвиняли лицемеры, после чего Всевышний Аллах объявил о её непричастности в аятах Корана, которые читаются. И нет разницы, верят в это шииты или не верят. Пусть Аллах поступит со лжецами и теми, кто их поддерживает, так, как они того заслуживают! И, поистине, мы принадлежим Аллаху, и к Нему мы вернемся!"]],[["p","И посмотри, как в конце своих слов он привёл этот аят: <b>«Аллах вернул неверующих…». </b>Он обвиняет госпожу ′Аишу в неверии, хотя он сам иногда после её упоминания говорит: «Да будет доволен ею Аллах». См. стр. 229. А на стр. 238 он признаёт, что она обладала достоинством и занимала высокое место."],["p","И он делает это только по одной причине — это известная среди шиитов «тукья» (сокрытия истинных убеждений). А иначе, как можно совместить это и то, что он упоминает её в числе неверующих?! Пусть Аллах поступит с ним так, как он заслуживает!»."],["sep",""],["h3","<b>Также сказал наш шейх в «ад-Да′ифа», 10/704, после хадиса № 4965: </b>"],["p","«Шиит также использовал этот ложный хадис неподобающим образом. Он посредством него стал ругать госпожу ′Аишу (да будет доволен ею Аллах), заявив, что она солгала. Точно также он ругал её посредством предыдущего хадиса»."],["sep",""],["h3","<b>Также сказал наш шейх в «ад-Да′ифа», 10/713-715, после хадиса № 4969</b><sup class=\"fn\">282</sup><b>:</b>"],["n",[[282,"Этот хадис является выдуманным (мауду′). В нём говорится, что пророк (да благословит его Аллах и приветствует) скончался, прислонившись к груди ′Али (да будет доволен им Аллах), и что ′Аиша (да будет доволен ею Аллах) якобы лгала, что он умер, прислонившись к ней."]]],["p","«Я скажу: эти хадисы являются выдуманными, но шиит ′Абд уль-Хусейн не стесняется (впрочем, это обычное для него дело) аргументировать ими против хадиса, который передаёт ′Аиша, так как её слова противоречат тому, что в этих (выдуманных) хадисах. Он поместил их в главе под названием: «Достоверные хадисы, противоречащие заявлениям матери верующих», стр. 247-252. Он не отнёс эти хадисы ни к кому, кроме Ибн Са′да. И как ты видишь, все эти хадисы передал аль-Уакыди, который был лжецом. Да и другие передатчики, помимо него, не являются надежными."],["p","Но шиит не остановился на этом. Он стал аргументировать тем, что пришло в книге «Нахдж аль-баляга» и в её толковании, которое принадлежит му′тазилиту Ибн уль-Хадиду. Также он стал аргументировать хадисом со слов Умм Салямы, который мы приводили под № 4945<sup class=\"fn\">283</sup>. Этот хадис является слабым, как мы уже говорили. Но шиит отдал этим хадисам предпочтение над словами самой ′Аиши, которые переданы по многочисленным и достоверным путям передачи. Затем он начал порочить её и злословить о ней, используя некоторые факты, которые достоверно переданы о ней. Впрочем, это является обычным делом для людей, которые не защищены от ошибок<sup class=\"fn\">284</sup>. Например, он упомянул её участие в верблюжьей битве. Но ведь она раскаялась в этом. Также он упомянул такие факты, в которых вообще нет повода для какого-либо упрека. Например, то, что пророк (да благословит его Аллах и приветствует) молился в её сторону, а она вытянула ноги. Также он упомянул такие факты, которые вообще не являются достоверными. В этом он опирался на книги по истории, в которых передаётся всё подряд. Особенно книга «Шарх Нахдж аль-баляга», которую написал му′тазилит Ибн уль-Хадид. Об этом можно говорить очень долго, но в этом нет никакой нужды."],["n",[[283,"Этот хадис также является выдуманным (мауду′)."],[284,"То есть даже если ′Аиша и совершала какие-то ошибки, то это является нормальным, так как от ошибок защищены только пророки. Это не повод бранить и ругать её, так как её достоинства известны любому мусульманину."]]]],[["p","Однако мы должны обсудить то, что стало затруднительным для тех, у кого нет знаний о путях передачи и версиях хадисов. Мы должны обсудить хитрость этого шиита, его скверну и его заблуждения, и то, как он ругает суннитов в целом и ругает мать верующих, которая была правдивейшей, дочерью правдивейшего. Речь идёт о том, что аль-Бухари передал, что ′Абдуллах ибн ′Умар сказал:"],["p","<i>«Однажды пророк (да благословит его Аллах и приветствует) встал, чтобы обратиться к людям с проповедью, и указал в сторону жилища ′Аиши, и трижды сказал: </i><b><i>\"Там смута! Оттуда появится рог шайтана!\"». </i></b>"],["p","В версии, которую передал Муслим, сказано: <i>«Однажды посланник Аллаха (да благословит его Аллах и приветствует) вышел из дома ′Аиши и сказал: </i><b><i>\"Глава неверия (появится) оттуда! И оттуда появится рог шайтана!\"».</i></b>"],["p","Шиит (′Абд уль-Хусейн) пытается внушить своим читателям, что под «смутой» в хадисе имеется в виду ′Аиша, да будет доволен ею Аллах. Аллах же объявил о её непричастности к этому так же, как объявил о её непричастности к тому, в чём её обвиняли лицемеры прежде!"],["p","Если же человек внимательно рассмотрит разные версии этого хадиса (не говоря уже о том, кто соберет все его версии), он точно поймет, что, когда пророк (да благословит его Аллах и приветствует) сказал: <b><i>«…оттуда…», </i></b>он имел в виду восток, то есть направление в сторону Ирака. И действительность свидетельствует о том, что эта сторона — источник смут как в старые, так и в современные времена."],["p","Я собрал все пути передачи и версии этого хадиса в книге «ас-Сахиха», хадис № 2494. Там я вкратце собрал для тебя то, чего достаточно для разоблачения лжи и клеветы этого шиита, и нет нужды повторять это здесь»."],["sep",""],["p","ВОПРОС № 19: КАК ШИИТ ′АБД УЛЬ-ХУСЕЙН ТОЛКУЕТ СЛОВА ВСЕВЫШНЕГО АЛЛАХА: «СКАЖИ: \"Я НЕ ПРОШУ У ВАС ЗА ЭТО НИКАКОЙ НАГРАДЫ, КРОМЕ ЛЮБВИ К МОИМ БЛИЗКИМ РОДСТВЕННИКАМ\"»<sup class=\"fn\">285</sup>."],["n",[[285,"Сура «аш-Шура», аят 23."]]],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «ад-Да′ифа», 10/726, после хадиса № 4974</b><sup class=\"fn\">286</sup><b>:</b>"],["n",[[286,"В этом хадисе пришло, что Ибн ′Аббас (да будет доволен Аллах им и его отцом) рассказывал: <i>«Когда были ниспосланы (слова Аллаха): </i><b>«Скажи: \"Я не прошу у вас за это никакой награды, кроме любви к моим близким родственникам\"», </b><i>люди спросили: \"О посланник Аллаха! А кто эти близкие родственники, которых мы обязаны любить?!\". Он ответил: </i><b><i>\"′Али, Фатыма и два их сына\"». </i></b>Хадис является ложным (батыль)."]]],["p","«Шиит ′Абд уль-Хусейн в своей книге «аль-Мураджа′ат», стр. 33, разъяснил этот аят посредством того, о чем говорится в этом ложном хадисе, но не обратил внимания на то, что этот аят был ниспослан в Мекке<sup class=\"fn\">287</sup>, и на то, что Ибн ′Аббас разъяснял этот аят совсем иначе (в том, что достоверно пришло от него)»<sup class=\"fn\">288</sup>."],["n",[[287,"То есть тогда еще не было ни аль-Хасана, ни аль-Хусейна, а ′Али еще не женился на Фатыме."],[288,"Это толкование от него передали аль-Бухари, Ахмад и ат-Табари в своём толковании Корана. Дело в том, что в этом аяте сказано: (<span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">إِلَّا</span> <span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">الْمَوَدَّةَ</span> <span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">فِي</span> <span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">الْقُرْبَىٰ</span>) /илля аль-мауаддата филь курба/, и эти слова можно понять по-разному. В названии главы мы перевели их так, чтобы это соответствовало тому, о чем говорит шиит, дабы читатель понял, что он имеет в виду. Мы перевели их так: <b>«…кроме любви к моим близким родственникам…». </b>Затем шиит привёл толкование Ибн ′Аббаса, которое недостоверно от него. Достоверно же пришло другое толкование. Ибн ′Аббас (в том, что достоверно от него) понимал слова (<span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">إِلَّا</span> <span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">الْمَوَدَّةَ</span> <span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">فِي</span> <span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">الْقُرْبَىٰ</span>) /илля аль-мауаддата филь курба/ иначе. Тавус рассказывал: <i>«Однажды некий человек спросил Ибн ′Аббаса о значении слов Всемогущего и Великого Аллаха: </i><b>«Скажи: \"Я не прошу у вас за это никакой награды, кроме</b> (<span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">إِلَّا</span> <span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">الْمَوَدَّةَ</span> <span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">فِي</span> <span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">الْقُرْبَىٰ</span>) /илля аль-мауаддата филь курба/». <i>Са′ид ибн Джубейр ответил: «Имеются в виду близкие родственники Мухаммада (да благословит его Аллах и приветствует)». </i>То есть его толкование соответствует тому, как мы изначально перевели аят: <b>«Скажи: \"Я не прошу у вас за это никакой награды, кроме любви к моим близким родственникам\"». </b> Далее Тавус продолжил: <i>«Но Ибн ′Аббас сказал: «Ты поторопился! Какой бы род курейшитов не жил в Мекке, у посланника Аллаха (да благословит его Аллах и приветствует) обязательно была с ними родственная связь. Но слова: </i><b>«Скажи: \"Я не прошу у вас за это никакой награды, кроме</b> (<span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">إِلَّا</span> <span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">الْمَوَدَّةَ</span> <span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">فِي</span> <span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">الْقُرْبَىٰ</span>) /илля аль-мауаддата филь курба/» <i>означают следующее: я не прошу у вас за это никакой награды, кроме того, чтобы вы укрепляли ту связь, которая между мной и вами!». </i> Согласно этому толкованию аят можно перевести так: <b>«Скажи: \"Я не прошу у вас за это никакой награды, кроме любви ради моей близости к вам\"». </b>А Аллах знает лучше!"]]],["h2","ГЛАВА № 5 — СУФИИ"],["h2","ВОПРОС № 1: СУФИИ ЗАЯВЛЯЮТ, ЧТО ИХ «СВЯТЫМ» (АУЛИЯ) ОТКРЫВАЮТСЯ ЗНАНИЯ"]],[["p","<b>Наш шейх, да помилует его Всевышний Аллах, в книге «ас-Сахиха» привёл следующий хадис под № 1110: </b><i>«Однажды ′Умар (да будет доволен им Аллах) обращался с проповедью к людям в пятничный день и сказал: \"О Сария</i><sup class=\"fn\">289</sup><i>! Гора! О Сария! Гора!\"». </i><b>Затем шейх сказал (3/102-104):</b>"],["n",[[289,"В этой истории говорится о том, что ′Умар (да будет доволен им Аллах) однажды отправил военный отряд, а руководителем этого отряда назначил человека по имени Са́рия. ′Умар, находясь в Медине, обратился к руководителю войска, и тот услышал его зов. Это является чудом от Всевышнего Аллаха."]]],["p","«Из вышесказанного мы понимаем, что ни один из этих путей передачи не является достоверным, кроме передачи Ибн ′Аджляна. В его передаче говорится лишь о том, что ′Умар обратился к ним со словами: «О Сария! Гора!», а войско услышало его зов и одержало по этой причине победу."],["p","Нет никаких сомнений в том, что этот зов был внушением от Всевышнего Аллаха ′Умару, и это не является удивительным, когда речь идёт о нём. Ведь он «аль-мухаддас» (тот, кому внушались правильные мысли), как это достоверно передано от пророка (да благословит его Аллах и приветствует). Но в этой истории не говорится о том, что ′Умару было открыто то, что происходит с войском, и что он увидел их воочию."],["p","Некоторые суфии аргументируют этой историей в пользу того, что они называют «кашфом» (открытием знаний) для своих «аулия» («святых»), и в пользу того, что их «аулия» («святые») могут видеть то, что в сердцах людей. Это является одним из самых ложных видов ложных убеждений. А как же иначе, если это — атрибут Господа миров?! Только Он один обладает знанием скрытого и видит то, что в груди людей. Мне интересно, как эти люди могут утверждать подобные ложные убеждения, когда Аллах говорит в Своей Книге: <b>«Он — Ведающий сокровенное, и Он не открывает Своего сокровенного никому, кроме тех посланников, которыми Он доволен»</b><sup class=\"fn\">290</sup>. Неужели они убеждены в том, что эти «аулия» являются посланниками от Аллаха, чтобы можно было сказать, что они могут видеть скрытое по причине того, что Аллах открыл им это?! Пречист Ты, о Аллах! Это — великая клевета!"],["n",[[290,"Сура «аль-Джинн», аяты 26-27."]]],["p","И даже если мы назовём то, что случилось с ′Умаром (да будет доволен им Аллах), словом «кашф» (открытие знаний), то это является необычным явлением, но такие необычные явления могут исходить даже от неверующих. Если от какого-то человека исходит что-то необычное, это само по себе не указывает на наличие у него веры (имана), не говоря уже о том, чтобы это указывало на его близость к Аллаху. Поэтому ученые говорят, что если какое-то необычные явление изойдет от мусульманина, то это называется словом «карамат» (чудо от Аллаха). В противном же случае это является завлечением (истидрадж). А в качестве примера они приводят те чудеса, которые будет являть людям ад-Даджжаль в конце времен. Например, он скажет небесам: «Пролейтесь дождем!», и они прольются дождем. И он скажет земле: «Взрасти свои растения!», и она взрастит растения. Он будет совершать многие другие чудеса, которые описаны в достоверных хадисах."]],[["p","Я приведу тебе еще один современный пример на эту тему. Недавно я прочитал в журнале «аль-Мухтар» статью под заголовком «Этот мир переполнен загадками, выходящими за рамки того, что человек воспринимает органами чувств». В этой статье говорилось о том, что юная девушка отправила на юг Африки, чтобы выйти замуж за своего жениха. Затем между ними произошли тяжелые ссоры, и она, спустя три недели, разорвала помолвку. После этого девушка стала ходить туда-сюда по своей комнате, испытывая замешательство, и беспрерывно восклицала: «О мамочка! О мамочка! Что же я делаю?!»<sup class=\"fn\">291</sup>. Но в итоге она решила не тревожить свою мать и не стала рассказывать ей о том, что произошло. А через четыре недели она получила от матери письмо, в котором было сказано: «Что случилось?! Я спускалась по лестнице и услышала, как будто ты кричишь: «О мамочка! О мамочка! Что же я делаю?!». А день, в который было написано письмо матерью, совпадал с тем днём, когда девушка обращалась с этими восклицаниями."],["n",[[291,"Следует учесть, что они находились в разных странах и очень далеко друг от друга, а она просто восклицала, обращаясь к матери, из-за своего горя."]]],["p","В этой статье приводились и другие примеры, которые можно отнести к тому, что сегодня называют «тахатур» (телепатия) и «истишфаф» (предугадывание; проницательность). Мы же ограничимся той историей, что мы упомянули, ибо эта история более всего похожа на историю ′Умара (да будет доволен им Аллах). Причём я часто слышу, что некоторые мусульмане отвергают эту историю, говоря, что подобное не поддаётся разуму, или же что-то эта история приписывает ′Умару наличие скрытых знаний. При этом мы видим и другую сторону, а именно тех, на кого мы указали, то есть суфиев, которые используют эту историю для того, чтобы утвердить наличие у «аулия» возможностей видеть скрытые. И те, и другие ошибаются."],["p","История является достоверной и установленной. И это — чудо, которым Всевышний Аллах почтил ′Умара. Посредством него Аллах спас войско мусульман от попадания в плен или погибели. Но в этой истории нет того притязания на наличие скрытого знания, о котором говорят суфии. В шариате это называется словом «ильхам» (внушение), а в современном мире это называют словом «тахатур» (телепатия). Но человек, которому даровано подобное, не является защищенным от ошибок. Иногда он бывает прав, как это случилось в данной истории, а иногда ошибается, как это случается с людьми в подавляющем большинстве случаев."],["p","Именно поэтому каждый «уалий» (приближенный Аллаха) должен ограничивать себя рамками шариата во всех словах и поступках, которые исходят от него, чтобы не впасть в противоречие религии, ибо из-за этого он может выйти за рамки «уилая» (близость к Аллаху). Всевышний Аллах весьма подробно и всеохватно описал нам, что такое «уилая» (близость к Аллаху), сказав: <b>«Воистину, угодники Аллаха (аулия) не познают страха и не будут опечалены. Они уверовали и остерегались (наказания Аллаха)»</b><sup class=\"fn\">292</sup>. И прекрасно сказал поэт:"],["n",[[292,"Сура «Юнус», аяты 62-63."]]],["c","<i>«Если ты увидишь, что человек летает,</i>"],["c","<i>И по морской воде ступает,</i>"],["c","<i>Но не останавливается у границ шариата,</i>"],["c","<i>То он — всего лишь обольщенный сторонник новшеств!». </i>"],["sep",""],["h2","ВОПРОС № 2: СУФИИ И ОТКАЗ ОТ ПОКЛОНЕНИЯ И ЗАРАБОТКА"]],[["p","<b>Наш шейх, да помилует его Всевышний Аллах, в книге «Сахих ат-Таргыб» привёл хадис под № 1216: <i>«Нахождение на страже на пути Аллаха (рибат) в течение одного дня лучше, чем этот мир и то, что в нём…». </i>Затем шейх сказал (2/64):</b>"],["p","«Рибат (<span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">الرباط</span>) — это нахождение на территории между неверующими и мусульманами, чтобы защищать от них мусульман."],["p","Я скажу: к этому не имеет никакого отношения нахождение суфиев в своих молельнях, отказ в них от поклонения Аллаху и от заработка, когда они заявляют, что их «обеспечивает Тот, Кто является создателем всех причин». Как же можно считать это верным, если Аллах сказал: <b>«Когда же молитва завершится, то разойдитесь по земле и ищите милость Аллаха»</b><sup class=\"fn\">293</sup>?"],["n",[[293,"Сура «аль-Джуму′а», аят 10."]]],["p","Именно поэтому ′Умар (да будет доволен им Аллах) сказал: <i>«Пусть ни один из вас не сидит в мечети, говоря: \"Аллах наделит меня пропитанием!\". Вы знаете, что с небес не льётся ни золото, ни серебро!». </i>"],["sep",""],["h2","ВОПРОС № 3: СУФИИ И ВЫХОД В ПУТЬ В ОДИНОЧКУ, А ТАКЖЕ ТРЕНИРОВКА ИМИ СВОИХ ДУШ В ПУСТЫНЯХ"],["p","<b>Наш шейх, да помилует его Всевышний Аллах, в книге «ас-Сахиха» привёл хадис под № 62: <i>«Один всадник — это шайтан, два всадника — это два шайтана, а трое — это караван (людей)»</i></b><sup class=\"fn\">294</sup>. <b>Затем он сказал (1/132):</b>"],["n",[[294,"Ибн Хузейма привел этот хадис в главе, которую он назвал следующим образом: <i>«Глава о запрете отправляться в путь вдвоем, а также указание на то, что люди, отправляющиеся в путь в количестве меньше трех, ослушиваются (Аллаха). Ведь пророк (да благословит его Аллах и приветствует) сообщил, что один — это шайтан, а двое — это два шайтана. Похоже, что слово «шайтан» в этом хадисе означает «ослушник», подобно словам Аллаха: </i><b>«…шайтаны из числа людей и джиннов…».</b><i> (Сура «аль-Ан′ам», аят 112). То есть ослушники из числа людей и джиннов».</i>"]]],["p","«Вероятно, в хадисе речь идёт о путешествиях через пустыни, в которых путник очень редко встречает людей. То есть сюда не относятся сегодняшние путешествия, когда человек передвигается по дорогам, переполненным автомобилями и людьми. А Аллах знает лучше!"],["p","Затем в этом хадисе ясное опровержение некоторым суфиям, которые выходят в путь через пустыни в одиночку, и, как они утверждают, тренируют свои души. Во время таких путешествий они часто подвергают себя смерти из-за жажды или голода или же бывают вынуждены побираться у людей. Это передаётся в историях о них, а лучшим руководством является руководство Мухаммада (да благословит его Аллах и приветствует)."],["sep",""],["h3","<b>Также в послании «Как мы должны толковать Священный Коран?» сказано следующее:</b>"],["p","<b>Вопрос № 1</b>: «Уважаемый шейх! В одной из брошюрок я прочитал следующий хадис: «Бери из Корана, что пожелаешь для того, чего пожелаешь!». Является ли этот хадис достоверным?! Ответьте нам, и да воздаст вам Аллах благом!»."]],[["p","<b>Ответ</b>: этот хадис «бери из Корана, что пожелаешь для того, чего пожелаешь!» распространен на языках некоторых людей. Но, к большому сожалению, он относится к числу тех хадисов, у которых нет никакой основы в Сунне. Именно поэтому запрещено передавать его и относить его к пророку (да благословит его Аллах и приветствует)."],["p","Затем этот смысл, (содержащийся в этих словах), не является достоверным и абсолютно не установлен в исламском шариате: «Бери из Корана, что пожелаешь для того, чего пожелаешь!». Например, я решил сидеть дома и не заниматься своим ремеслом, а просить удела у своего Господа, чтобы Он ниспослал его мне с небес. Получается, я могу извлечь подобное из Корана?! Кто скажет подобное?!"],["p","Эти слова являются ложными. Вероятно, их выдумали те ленивые суфии, натурой которых является сидение и пребывание в тех местах, которые они именуют «рибатами» (суфийские кельи). Они сидят в них и ожидают «удела Аллаха» от тех людей, которые к ним приходят. Следует знать, что подобное не является чертой мусульманина, ведь пророк (да благословит его Аллах и приветствует) воспитывал всех мусульман на возвышенных устремлениях и чувстве собственного достоинства. Например, он сказал: <b><i>«Высшая рука лучше низшей руки. Высшая рука — это рука расходующая, а низшая рука — это рука просящая!»</i></b><sup class=\"fn\">295</sup>."],["n",[[295,"Аль-Бухари и Муслим."]]],["p","На эту тему меня удивило то, что я читал из историй некоторых аскетов и суфиев. Я не буду говорить много. На самом деле, от них передано много подобных удивительных историй."],["p","Так вот, они рассказывают, что один из них вышел в путешествие без провизии, и дело дошло до того, что он уже почти умер от голода, но вдруг вдали ему показалась деревня, и он отправился в неё. Это случилось в пятницу. Этот человек считал, что он вышел в путь, уповая на Аллаха. И вот, чтобы не разрушить своё «упование» на Аллаха, он не стал показывать себя тем людям, которые находились в мечети. Он спрятался под минбаром, чтобы никто не знал о его присутствии. После этого проповедник обратился к людям с пятничной проповедью, а этот (спрятавшийся суфий) не совершил молитву вместе с коллективом мусульман. Когда же имам завершил проповедь и молитву, люди начали выходить из мечети группами и по одиночке, после чего он понял, что мечеть уже почти опустела. После этого двери мечети заперли, и он остался в мечети один без еды и питья. Тогда он начал слегка кашлять, чтобы дать понять людям, оставшимся в мечети, что он находится среди них, ибо у него уже не было иного выхода. Некоторые люди осмотрелись по сторонам и увидели его изможденное от голода и жажды состояние. Тогда они взяли его и помогли ему."]],[["p","Они стали спрашивать его: «Кто ты такой?», на что он ответил: «Я — аскет, уповающий на Аллаха!». Они сказали: «Как ты называешь себя уповающим на Аллаха?! Ты чуть было не умер! Если бы ты «уповал» на Аллаха, ты бы не стал просить нас и не стал бы давать нам понять своё присутствие путем покашливания, а умер бы со своим грехом»."],["p","Это — пример того, к чему приводят подобные «хадисы»: «Бери из Корана, что пожелаешь для того, чего пожелаешь!». Суть в том, что у этого хадиса нет никакой основы»."],["sep",""],["h2","ВОПРОС № 4: СУФИИ И МОЛЬБА (ДУ′А)"],["p","<b>Наш шейх, да помилует его Всевышний Аллах, в книге «Сахих ат-Таргыб» привёл следующий хадис под № 1200: <i>«О Аллах! Внуши нам такую любовь к Медине, которая подобна нашей любви к Мекке или даже больше! Оздорови для нас ее (воду и климат) и даруй нам благодать в ее са’ и муддах! Перенеси лихорадку (Медины) и помести ее в Джухфе!».</i> Затем шейх сказал (2/56):</b>"],["p","«Сказал аль-Хаттаби и другие: <i>«В этом хадисе содержится обращение с мольбой о здравии для мусульман, а также о том, чтобы их город подходил им, и чтобы в нём присутствовала благодать (барака), и чтобы Аллах удалил от них вред и беды. И это — мазхаб всех ученых!».</i>"],["p","Сказал аль-Кады ′Ияд: <i>«И это противоречит словам некоторых суфиев о том, что обращение с мольбой к Аллаху — это недостаток в уповании и довольстве, и что следует оставить мольбы. Также это противоречит словам му′тазилитов о том, что в мольбах нет никакой пользы, ибо все уже предопределено». </i>"],["sep",""],["h2","ВОПРОС № 5: СУФИИ И ТАНЦЫ ВО ВРЕМЯ ПОМИНАНИЯ АЛЛАХА"],["p","<b>Наш шейх, да помилует его Всевышний Аллах, в книге «ас-Сахиха» привёл хадис под № 1317, в котором сказано, что пророк (да благословит его Аллах и приветствует) сказал: <i>«Муфарридуна опередили (остальных)». </i>Люди спросили:</b> <i>«О посланник Аллаха! А кто такие муфарридуна?». </i><b>Он ответил: <i>«Те, которые поглощены поминанием Аллаха». </i>Затем он сказал (3/306-307):</b>"],["p","«В этом хадисе сказано: <b>«йюхтаруна»</b> (<span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">يُهتَرون</span>), что означает «поглощены». Ибн уль-Асир сказал: <i>«Речь идёт о том, кто поглощен этим (поминанием Аллаха). Он не говорит ничего другого и не делает ничего другого». </i>"],["p","<b>Примечание</b>: я привёл этот хадис по следующей причине: в книге «аш-Шу′аб» этот хадис пришёл со словом <b>«йахтаззуна»</b> (<span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">يهتزون</span>) (трясутся, качаются). Именно поэтому я поспешил исследовать этот хадис, так как боялся, что некоторые суфии-танцоры станут аргументировать им в пользу дозволенности тех танцев и качаний в разные стороны, которые они практикуют во время поминания Аллаха. Они либо не знают, либо делают вид, что не знают о том, что данная версия хадиса является искаженной. Также им в этом вопросе помогает то, что пришло в «Шарх Сахих Муслим» ан-Науауи, где сказано: <i>«И пришло в одной из версий: \"Это — те, которые трясутся во время поминания Аллаха\". То есть они поглощены поминанием Аллаха». </i>"]],[["p","Даже если бы эта версия была достоверной, то она имела бы следующий смысл: они радуются поминанию Аллаха, чувствуют умиротворение во время поминания Аллаха. Именно это извлекается из корня «ха-за-за» (<span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">هزز</span>), как это пришло в книге «ан-Нихая». В таком случае это соответствовало бы словам пророка (да благословит его Аллах и приветствует): <b><i>«Позволь нам отдохнуть в молитве, о Биляль!». </i></b>И это близко к тому смыслу, на который указал ан-Науауи. А Аллах знает лучше!"],["p","Здесь я обязательно должен обратиться с напоминанием, ибо я искренне желаю добра этой общине. Дело в том, что некоторые суфии упоминают, что ′Али (да будет доволен им Аллах) будто бы сказал, описывая сподвижников пророка (да благословит его Аллах и приветствует):"],["p","<i>«Когда они поминали Аллаха, они качались, как качается дерево в ветреный день». </i>"],["p","Знай, что это не является достоверным от него. Эти слова передал Абу Ну′айм в «аль-Хилья», 1/76, от Мухаммад ибн Язида Аби Хишама, которому рассказал аль-Мухариби от Малика ибн Мигваля, а тот — от человека из Джу′фы, который передавал от ас-Судди, а тот — от Абу Араки, а тот — от ′Али."],["p","Я скажу: эта цепочка передатчиков является слабой и мрачной."],["p","1) Абу Арака — я его не знаю и я не нашел, чтобы хоть кто-то его упоминал. Только лишь ад-Дауляби упомянул в книге «аль-Куна» человека по имени Абу Арак, который жил примерно в то время, а затем привел предание, которое этот Абу Арак передавал от ′Абдуллаха ибн ′Амра. Но он не упомянул в отношении этого передатчика ни критики, ни похвалы, что ему свойственно."],["p","2) Человек из Джу′фы — его имя не названо. То есть этот передатчик является неизвестным (маджхуль)."],["p","3) Мухаммад ибн Язид. Аль-Бухари сказал: <i>«Я видел, что ученые единогласны в его слабости». </i>"],["sep",""],["p","<b>Также наш шейх в книге «ад-Да′ифа» упомянул под № 115 следующий выдуманный хадис: <i>«Растворяйте вашу пищу посредством поминания Аллаха и молитвы, и не спите, когда поели досыта, ибо из-за этого ваши сердца станут черствыми»</i></b><sup class=\"fn\">296</sup><b><i>. </i>Затем он сказал, 1/234-235: </b>"],["n",[[296,"В книге «ад-Да′ифа», 14/1147, аль-Альбани также указал на то, что этот хадис выдумали именно последователи тарикатов. И он сказал: <i>«Как же прекрасен тот, кто сказал о них: </i> <i> «Поколение сторонников новшеств — худшее поколение,</i> <i>Вы совершаете абсурдные поступки!</i> <i>Неужели мой Бог сказал вам в Коране:</i> <i>\"Ешьте, словно животные, а потом танцуйте ради Меня\"?!». </i>"]]],["p","«Знай, что больше всего этому выдуманному хадису радуются те пожиратели еды и танцоры, которые набивают свои животы различными видами еды и питья, а затем встают, берут друг друга за руки и поминают (как они думают!) Всевышнего Аллаха, качаясь вправо и влево, вперед и назад. При этом они волнительным голосом читают красивые стихотворения, пока не «растворится» то, что в их животах. При всё этом они думают, что поступают хорошо. И правдив тот, кто сказал:"],["c","<i>«С каких пор в нашей религии людей обучили</i>"],["c","<i>Тому, что песни — это сунна, за которой надо следовать?!</i>"],["c","<i>И тому, что человек должен есть, как осёл,</i>"],["c","<i>И танцевать группами до потери сил. </i>"],["c","<i>Они говорят: \"Мы опьянели от любви к Аллаху!\",</i>"],["c","<i>Но их опьянили только лишь подносы еды. </i>"],["c","<i>Точно так и животные, когда насытятся,</i>"],["c","<i>Танцуют из-за утоления жажды и чувства сытости.</i>"],["c","<i>Где же рассудки?! Где же разумы?!</i>"],["c","<i>Неужели никто из вас не станет порицать новшества?!</i>"],["c","<i>Они унижают наши мечети песнями,</i>"],["c","<i>Подобного нет даже в церквях!». </i>"],["sep",""]],[["p","<b>Также наш шейх в книге «ад-Да′ифа» упомянул под № 558 следующий хадис: <i>«Не является благородным тот, кто не чувствует волнения при упоминании Любимого». </i>Затем он сказал, 2/34:</b>"],["p","«Хадис выдуманный (мауду′). Его упомянул Мухаммад ибн Тахир аль-Макдиси в «Сафуат ат-тасаввуф». Также от него этот хадис упомянул Абу Хафс ′Умар ас-Сухраварди, автор книги «′Ауариф аль-ма′ариф». Они передали, что однажды некий бедуин прочитал перед пророком (да благословит его Аллах и приветствует) следующее стихотворение:"],["c","<i>«Змея страсти ужалила меня в печень,</i>"],["c","<i>И теперь не поможет ей ни лекарь, ни читающий заговоры!</i>"],["c","<i>Кроме любимого, которым я страстно увлечен.</i>"],["c","<i>Лишь у него моё заклинание и противоядие». </i>"],["p","И после этого он почувствовал волнение так, что с его плеч даже упала накидка. Увидев это, Му′ауия сказал: <i>«Как прекрасны ваши развлечения!». </i>На что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Не торопись, о Му′ауия! Не является благородным тот, кто не чувствует волнения при упоминании Любимого».</i></b>"],["p","Сказал Ибн Теймия в послании «ас-Сама′ уа рракс» (Песни и танцы):"],["p","<i>«Этот хадис является лживым и выдуманным по единогласному мнению знатоков хадисов. Этот и подобные хадисы передают только самые невежественные люди в отношении пророка (да благословит его Аллах и приветствует), его сподвижников и их последователей». </i>"],["p","Я скажу: затем я вернулся к книге «Сафуат ат-тасаввуф» хафиза Ибн Тахира аль-Макдиси, но не нашел в ней этот хадис. Однако хафиз (Ибн Хаджар) в «Лисан аль-мизан» отнес этот хадис к другой его книге под названием «ас-Сама′». А цепочку этого хадис привёл ас-Сухраварди в «аль-′Ауариф», стр. 108-109. Этот хадис передан от Абу Бакра ′Аммара ибн Исхака, которому рассказал Са′ид ибн ′Амир от Шу′бы, который передал от ′Абд уль-′Азиза ибн Сухейба, а тот — от Анаса. Затем ас-Сухраварди сказал:"],["p","<i>«Мы передали этот хадис с непрерывной цепочкой до пророка (да благословит его Аллах и приветствует) так, как мы услышали его и нашли. Его достоверность критиковали знатоки хадисов. И если вести речь об экстазе, который постигает людей в наши дни, и о том, что они слушают песни и собираются (для этого), то мы не нашли об этом ничего от посланника Аллаха (да благословит его Аллах и приветствует), кроме этого хадиса. И как он прекрасен в качестве довода для суфиев и наших современников, которые слушают песни и рвут на себе одежду, а затем распределяют её среди людей, но это всё при условии, если бы он был достоверным. Моё сердце подсказывает мне, что этот хадис не является достоверным. Я не нашёл в нём ощущение того, как обычно пророк (да благословит его Аллах и приветствует) собирался со своими сподвижниками. Моё сердце отказывается его принять!». </i>"]],[["p","Я скажу: в этом хадисе проблема в передатчике по имени ′Аммар ибн Исхак. Аз-Захаби сказал в его биографии: <i>«Кажется, именно он выдумал эту ересь, в которой сказано: \"Змея страсти ужалила меня в печень…\". Ведь все остальные передатчики этой истории являются крепкими». </i>"],["sep",""],["p","ВОПРОС № 6: СУФИИ РАЗРЕШАЮТ ПЕСНИ И МУЗЫКАЛЬНЫЕ ИНСТРУМЕНТЫ, ОПИРАЯСЬ НА КНИГУ «ИДАХ АД-ДАЛЯЛЯТ ФИ САМА′ АЛЬ-АЛЯТ», АВТОРОМ КОТОРОЙ ЯВЛЯЕТСЯ ′АБД УЛЬ-ГАНИЙ АН-НАБЮЛЬСИ"],["p","<b>Наш шейх, да помилует его Всевышний Аллах, в книге «Сахих ат-Таргыб» привёл хадис под № 1449: <i>«Украшайте Коран своими голосами»</i></b>. <b>Затем он сказал (2/176): </b>"],["p","«Допустил грубую ошибку Ахмад Рабит Хамуш, когда делал примечания к посланию шейха ′Абд уль-Ганий ан-Набюльси под названием «Идах ад-далялят фи сама′ аль-алят» (Разъяснение доводов относительно слушания музыкальных инструментов). Он сказал: <i>«Этот хадис передали аль-Бухари, ад-Дарими, Ибн Ханбаль, Абу Дауд, ат-Тирмизи и ан-Насаи». </i>Это — удивительная путаница, ведь никто из них не передал этот хадис с этой добавкой, кроме ад-Дарими. Этот человек допустил много других грубых ошибок в своих многочисленных примечаниях к этой книжке. Одной из самых главных его ошибок является то, что такому, как он, не следовало помогать в распространении этой книги суфия, шейха ′Абд уль-Ганий<sup class=\"fn\">297</sup>, который в этой книге говорит о дозволенности музыкальных инструментов всех форм и видов, заявляя, что они могут быть дозволенными по причине благого намерения человека. То есть если человек, слушая музыку, имеет хорошее намерение, то тогда и музыка будет дозволенной."],["n",[[297,"Суфий ′Абд уль-Ганий ан-Набюльси написал это послание о дозволенности использования различных музыкальных инструментов. Оно было издано издательством «Дар уль-калям» в Дамаске. Этим и другими его посланиями аргументируют суфии в пользу дозволенности слушания музыки и т. п. Многие ученые ответили на это послание и разъяснили запретность музыки и музыкальных инструментов. И это мнение является правильным, и соответствующим Корану и Сунне. И вся хвала Аллаху!"]]],["p","Это напомнило мне историю, которая имело место между мной и одним из искателей знаний. Он пришёл ко мне в торговую лавку, чтобы отремонтировать свои часы, а я увидел, что он держит под рукой круглые пластины. Раньше их использовали для того, чтобы слушать музыку через аппарат, известный как фонограф. Я специально спросил его: «Ты поёшь?». Он ответил: «Нет, я не пою. Я слушаю». Я спросил: «А что ты слушаешь?». Он ответил: «Я слушаю Умм Кульсум. Я сажусь возле этого аппарата, держу в руках четки и слушаю, вспоминая о пении райских дев в Раю». Я сказал ему: «Горе вам!», или что-то подобное, «Я боюсь, что у одного из вас наступит такой день, когда вы объявите дозволенным распитие вина, говоря о том, что оно напоминает вам о райском вине»."]],[["p","Вот до такой степени дошли суфии, и одной из причин стало то, что шейх ′Абд уль-Ганий ан-Набюльси распространял эти заблуждения среди мусульман. Извлечет ли кто-нибудь из этого урок?!»."],["sep",""],["h2","ВОПРОС № 7: ПОСЛЕДОВАТЕЛИ СУФИЙСКИХ ТАРИКАТОВ И КОЛДОВСТВО"],["h3","<b>Наш шейх, да помилует его Всевышний Аллах, сказал в книге «ад-Да′ифа», 3/642, после хадиса № 1446: </b>"],["p","«И подобно этому убитому колдуну<sup class=\"fn\">298</sup> эти последователи тарикатов, которые показывают себя приближенными Аллаха и бьют себя мечами и рапирами. Часть этого является просто обманом глаз, а не истинным колдовством, а часть — это следствие опыта и тренировок. Каждый человек, будь он верующим или неверующим, сможет выполнить это, если будет практиковаться и будет обладать крепким духом. Также к этому относится то, что они прикасаются к огню своими ртами или руками и входят в горящую печь."],["n",[[298,"Там шейх аль-Альбани привёл историю, которую передал аль-Бейхакы. В ней говорится, что когда аль-Уалид ибн ′Укба пребывал в Ираке, перед ним игрался некий колдун. Он отрубал голову человека, а затем обращался к нему с криком и тот вставал, и тогда он возвращал его голову на место. Люди начали говорить: «Пречист Аллах! Он оживляет мертвых!». В этот момент его увидел один из праведных мухаджиров, и когда наступил следующий день, и тот колдун вновь занялся своими фокусами, этот мухаджир обнажил свой меч и отрубил ему голову, сказав: «Если он правдив, то пусть оживит самого себя!». Тогда аль-Уалид отдал повеление Динару (он был главой тюрьмы и праведным человеком) заключить этого сподвижника в тюрьму. Динар заключил его в тюрьму, а затем сказал: «Ты сможешь сбежать?». Тот ответил: «Да». Тогда Динар сказал: «Выходи! Пусть Аллах никогда не спросит у меня о тебе!». Цепочка передатчиков этой истории является достоверной."]]],["p","Однажды в Алеппо я встретился с одним из таких, и он сказал мне, что относится к числу таких людей, и что он может проткнуть себя рапирой и может держать в руке угли. Я обратился к нему с наставлением и разъяснил ему суть этого дела. Я пригрозил ему, что направлю на него огонь, если он не откажется от этих пустых заявлений, но он не стал отказываться. Тогда я подошёл к нему и поднёс огонь к его чалме, чтобы напугать его. Он же не стал отказываться от своих заявлений, и тогда я поджёг его чалму, а он смотрел (и ничего не предпринимал). Затем я потушил её, так как испугался, что он из-за своего упрямства сгорит. И я думаю, что если бы (этот сподвижник) Джундуб (да будет доволен им Аллах) увидел таких людей, он непременно казнил бы их мечом, как он сделал это с тем колдуном. <b>«А мучения в Последней жизни будут еще более тяжкими и длительными»</b><sup class=\"fn\">299</sup><b>»</b>."],["n",[[299,"Сура «Та Ха», аят 127."]]],["sep",""],["h2","ВОПРОС № 8: СУФИИ И МНОГОБОЖИЕ В АТРИБУТАХ АЛЛАХА"]]];
